<script setup lang="ts">import {computed,ref} from 'vue';import {Library,Endmember,SampleResult} from '../types/domain';import {number} from '../utils/format';const props=defineProps<{library:Library;endmembers:Endmember[];sample?:SampleResult}>();const references=ref(false);const all=computed(()=>props.sample?[...props.sample.observed,...props.sample.point_fit.reconstructed]:props.endmembers.flatMap(e=>e.spectrum));const low=computed(()=>Math.min(0,...all.value)-.04),high=computed(()=>Math.max(1,...all.value)+.04);const x=(i:number)=>65+i/(props.library.wavelengths.length-1)*815,y=(v:number)=>235-(v-low.value)/(high.value-low.value)*200;const line=(v:number[])=>v.map((n,i)=>`${i?'L':'M'}${x(i)},${y(n)}`).join(' ');</script><template><section class="spectral-plot"><div class="plot-toolbar"><h3>{{sample?'观测与重建光谱':'校准端元光谱'}}</h3><button v-if="sample" :class="{active:references}" @click="references=!references">{{references?'隐藏':'显示'}}端元参考</button><span v-else>反射率 / 无量纲</span></div><svg viewBox="0 0 940 280" aria-label="光谱观测重建曲线"><g v-for="i in [0,1,2,3,4]" :key="i"><line x1="65" x2="880" :y1="y(low+(high-low)*i/4)" :y2="y(low+(high-low)*i/4)" class="gridline"/><text x="54" :y="y(low+(high-low)*i/4)+4" text-anchor="end">{{number(low+(high-low)*i/4,2)}}</text></g><template v-if="!sample||references"><path v-for="(e,i) in endmembers" :key="e.code" :d="line(e.spectrum)" :class="['endmember-line','line-'+i]"/></template><template v-if="sample"><path :d="line(sample.observed)" class="observed-line"/><path :d="line(sample.point_fit.reconstructed)" class="reconstructed-line"/><circle v-for="(v,i) in sample.observed" :key="i" :cx="x(i)" :cy="y(v)" r="3" class="observed-point"/></template><text v-for="i in [0,Math.floor((library.wavelengths.length-1)/2),library.wavelengths.length-1]" :key="i" :x="x(i)" y="259" text-anchor="middle">{{library.wavelengths[i]}}</text><text x="890" y="259">nm</text></svg><div class="plot-legend"><template v-if="sample"><span><i class="observed"/>观测谱</span><span><i class="reconstructed"/>约束重建谱</span><small>线连接真实波段值，不作额外平滑</small></template><template v-else><span v-for="(e,i) in endmembers" :key="e.code"><i :class="'color-'+i"/>{{e.name}}</span></template></div></section></template>
